from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self._capacity = capacity
        self._ttl = ttl
        self._clock = clock
        self._cache = OrderedDict()
        self._stats = {
            "hits": 0,
            "misses": 0,
            "evictions": 0,
            "expirations": 0
        }

    def put(self, key, value):
        if self._capacity <= 0:
            return

        now = self._clock()

        if key in self._cache:
            # Update existing key: refresh expiry and recency
            self._cache.move_to_end(key)
            self._cache[key] = (value, now + self._ttl)
        else:
            # Insert new key
            # Check if capacity would be exceeded
            if len(self._cache) >= self._capacity:
                # First remove all expired entries
                expired_keys = [k for k, (_, exp) in self._cache.items() if now >= exp]
                for k in expired_keys:
                    del self._cache[k]
                    self._stats["expirations"] += 1

                # If still full, evict LRU
                if len(self._cache) >= self._capacity:
                    self._cache.popitem(last=False)
                    self._stats["evictions"] += 1

            # Insert the new key
            self._cache[key] = (value, now + self._ttl)

    def get(self, key, default=None):
        if self._capacity <= 0:
            self._stats["misses"] += 1
            return default

        now = self._clock()

        if key not in self._cache:
            self._stats["misses"] += 1
            return default

        val, exp = self._cache[key]

        if now >= exp:
            # Entry expired
            del self._cache[key]
            self._stats["expirations"] += 1
            self._stats["misses"] += 1
            return default

        # Entry valid
        self._cache.move_to_end(key)
        self._stats["hits"] += 1
        return val

    def __len__(self):
        now = self._clock()
        count = 0
        for _, (_, exp) in self._cache.items():
            if now < exp:
                count += 1
        return count

    def stats(self):
        return dict(self._stats)
