def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    # Sort and remove duplicates
    unique_nums = sorted(set(nums))

    parts = []
    start = unique_nums[0]
    prev = unique_nums[0]

    for num in unique_nums[1:]:
        if num == prev + 1:
            prev = num
        else:
            # End of a consecutive run
            if prev - start >= 2:
                parts.append(f"{start}..{prev}")
            elif prev - start == 1:
                parts.append(f"{start},{prev}")
            else:
                parts.append(str(start))
            start = num
            prev = num

    # Handle the final run
    if prev - start >= 2:
        parts.append(f"{start}..{prev}")
    elif prev - start == 1:
        parts.append(f"{start},{prev}")
    else:
        parts.append(str(start))

    return ",".join(parts)
