class TokenBucket:
    def __init__(self, capacity: float, refill_per_sec: float, clock):
        self._capacity = capacity
        self._refill_per_sec = refill_per_sec
        self._clock = clock
        self._tokens = capacity
        self._last_update_time = clock()

    def _refill(self):
        now = self._clock()
        elapsed = now - self._last_update_time

        if elapsed > 0:
            # Calculate new token count based on elapsed time
            self._tokens = min(
                self._capacity,
                self._tokens + elapsed * self._refill_per_sec
            )
            # Update the last update time to prevent double-counting
            self._last_update_time = now

    @property
    def tokens(self) -> float:
        self._refill()
        return self._tokens

    def allow(self, cost: float = 1) -> bool:
        self._refill()
        if self._tokens >= cost:
            self._tokens -= cost
            return True
        return False
